                            ans[i][j] = ans[i][j - 2] | ans[i - 1][j];
                        }
                    }
                } else if (p[j - 1] == '.') {
                    ans[i][j] = ans[i - 1][j - 1];
                } else {
                    ans[i][j] = ans[i - 1][j - 1] &
                        (s[i - 1] == p[j - 1]);
                }
            }
        }
        return ans[length1][length2];
